import { MeshStandardNodeMaterial } from 'three/webgpu';
import { texture, uv, mix, time, vec2, float } from 'three/tsl';
import { gsap } from 'gsap';
import * as primitives from '@/primitives';
import * as text from '@/text';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry } = ctx.THREE;

  // root object
  const root = new Group();
  root.userData.handlers = {};
  const cleanupFns = [];

  // geometry
  const geometry = new PlaneGeometry(7, 6, 64, 64);
  // material
  const material = new MeshStandardNodeMaterial();
  material.roughness = 0.6;
  material.metalness = 0.3;
  material.clearcoat = 0.1;
  material.displacementScale = 0.2;

  // mesh
  const mesh = new Mesh(geometry, material);
  root.add(mesh);

  // load texture
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      material.mapNode = texture(tex);
      material.needsUpdate = true;
    });
  }

  // load depth map for displacement
  if (config.depthMapUrl) {
    ctx.textureLoader.loadTexture(config.depthMapUrl).then((dtex) => {
      material.displacementNode = texture(dtex);
      material.needsUpdate = true;
    });
  }

  // apply cinematic primitives
  const primitiveRefs = [];
  const primitivesList = config.cinematicPrimitives ?? [];
  for (const p of primitivesList) {
    if (typeof ctx.primitives[p.name] === 'function') {
      const ref = ctx.primitives[p.name](root, p.params);
      primitiveRefs.push(ref);
      if (ref && typeof ref.cleanup === 'function') {
        cleanupFns.push(() => ref.cleanup());
      }
    }
  }

  // hover effect: rise-in (translate up 0.15 units)
  const hoverTimeline = gsap.timeline({ paused: true });
  hoverTimeline.to(mesh.position, {
    y: '+=0.15',
    duration: 0.7,
    ease: 'power3.out',
  });
  root.userData.handlers.hover = () => {
    hoverTimeline.restart();
  };
  cleanupFns.push(() => hoverTimeline.kill());

  // click effect: emit navigation event
  root.userData.handlers.click = () => {
    ctx.emit('hub-pricing.select', {});
  };

  // cleanup method
  root.userData.cleanup = () => {
    // dispose material and geometry
    material.dispose();
    geometry.dispose();
    // kill timelines
    cleanupFns.forEach((fn) => fn());
    // primitive cleanups already added
    // remove from parent if any
    if (root.parent) root.parent.remove(root);
  };

  return root;
}
